=== FILE: axi4_lite_regs.v ===
// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port.
//
// Implements interface_spec.md and microarchitecture.md:
//   * READY is a function of state only (no combinational path from a VALID
//     input to any output).
//   * Holding registers pair AW and W in any order; the write fires on the
//     edge that completes the pair.
//   * One outstanding transaction per direction; reads and writes are
//     independent.
//   * Unmapped (misaligned) addresses are answered with SLVERR; an unmapped
//     write changes nothing, an unmapped read returns zero.
//   * aresetn is active low and synchronous.
// The RTL never ends a simulation.

module axi4_lite_regs #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,

    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,

    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,

    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,

    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,

    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

  localparam integer STRB_WIDTH  = DATA_WIDTH / 8;
  localparam [1:0]   RESP_OKAY   = 2'b00;
  localparam [1:0]   RESP_SLVERR = 2'b10;

  // An address is mapped when it is word aligned and inside the 16-byte map.
  function is_mapped;
    input [ADDR_WIDTH-1:0] addr;
    begin
      is_mapped = (addr[1:0] == 2'b00) && ((addr >> 4) == {ADDR_WIDTH{1'b0}});
    end
  endfunction

  // ------------------------------------------------------------------
  // State (reset)
  reg                  aw_held_q;
  reg                  w_held_q;
  reg                  bvalid_q;
  reg  [1:0]           bresp_q;
  reg                  rvalid_q;
  reg  [1:0]           rresp_q;
  reg  [DATA_WIDTH-1:0] rdata_q;
  reg  [DATA_WIDTH-1:0] reg0_q;
  reg  [DATA_WIDTH-1:0] reg1_q;
  reg  [DATA_WIDTH-1:0] reg2_q;
  reg  [DATA_WIDTH-1:0] reg3_q;

  // Datapath holding registers (not reset; their held flags are)
  reg  [ADDR_WIDTH-1:0] aw_addr_q;
  reg  [DATA_WIDTH-1:0] w_data_q;
  reg  [STRB_WIDTH-1:0] w_strb_q;

  // Next state
  reg                  aw_held_d;
  reg                  w_held_d;
  reg                  bvalid_d;
  reg  [1:0]           bresp_d;
  reg                  rvalid_d;
  reg  [1:0]           rresp_d;
  reg  [DATA_WIDTH-1:0] rdata_d;
  reg  [DATA_WIDTH-1:0] reg0_d;
  reg  [DATA_WIDTH-1:0] reg1_d;
  reg  [DATA_WIDTH-1:0] reg2_d;
  reg  [DATA_WIDTH-1:0] reg3_d;
  reg  [DATA_WIDTH-1:0] rd_reg;

  // ------------------------------------------------------------------
  // Outputs: READY from state only
  assign s_axil_awready = !aw_held_q && !bvalid_q;
  assign s_axil_wready  = !w_held_q && !bvalid_q;
  assign s_axil_arready = !rvalid_q;
  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rresp   = rresp_q;
  assign s_axil_rdata   = rdata_q;

  // Handshakes
  wire aw_hs = s_axil_awvalid && s_axil_awready;
  wire w_hs  = s_axil_wvalid && s_axil_wready;
  wire ar_hs = s_axil_arvalid && s_axil_arready;
  wire b_hs  = bvalid_q && s_axil_bready;
  wire r_hs  = rvalid_q && s_axil_rready;

  // Write pairing
  wire                  do_write  = (aw_held_q || aw_hs) && (w_held_q || w_hs);
  wire [ADDR_WIDTH-1:0] wr_addr   = aw_held_q ? aw_addr_q : s_axil_awaddr;
  wire [DATA_WIDTH-1:0] wr_data   = w_held_q ? w_data_q : s_axil_wdata;
  wire [STRB_WIDTH-1:0] wr_strb   = w_held_q ? w_strb_q : s_axil_wstrb;
  wire                  wr_mapped = is_mapped(wr_addr);
  wire                  rd_mapped = is_mapped(s_axil_araddr);

  // Byte-enable mask: strobe bit n enables bits 8n+7:8n
  wire [DATA_WIDTH-1:0] wr_mask;
  genvar gi;
  generate
    for (gi = 0; gi < STRB_WIDTH; gi = gi + 1) begin : g_wr_mask
      assign wr_mask[8*gi +: 8] = {8{wr_strb[gi]}};
    end
  endgenerate

  wire [DATA_WIDTH-1:0] reg0_wr = (reg0_q & ~wr_mask) | (wr_data & wr_mask);
  wire [DATA_WIDTH-1:0] reg1_wr = (reg1_q & ~wr_mask) | (wr_data & wr_mask);
  wire [DATA_WIDTH-1:0] reg2_wr = (reg2_q & ~wr_mask) | (wr_data & wr_mask);
  wire [DATA_WIDTH-1:0] reg3_wr = (reg3_q & ~wr_mask) | (wr_data & wr_mask);

  // ------------------------------------------------------------------
  // Write side next state
  always @(*) begin
    aw_held_d = aw_held_q;
    w_held_d  = w_held_q;
    bvalid_d  = bvalid_q;
    bresp_d   = bresp_q;
    reg0_d    = reg0_q;
    reg1_d    = reg1_q;
    reg2_d    = reg2_q;
    reg3_d    = reg3_q;
    if (do_write) begin
      aw_held_d = 1'b0;
      w_held_d  = 1'b0;
      bvalid_d  = 1'b1;
      if (wr_mapped) begin
        bresp_d = RESP_OKAY;
        case (wr_addr[3:2])
          2'd0:    reg0_d = reg0_wr;
          2'd1:    reg1_d = reg1_wr;
          2'd2:    reg2_d = reg2_wr;
          2'd3:    reg3_d = reg3_wr;
          default: reg0_d = reg0_q;
        endcase
      end else begin
        bresp_d = RESP_SLVERR;
      end
    end else begin
      if (aw_hs) aw_held_d = 1'b1;
      if (w_hs)  w_held_d  = 1'b1;
      if (b_hs)  bvalid_d  = 1'b0;
    end
  end

  // Read side: register select
  always @(*) begin
    case (s_axil_araddr[3:2])
      2'd0:    rd_reg = reg0_q;
      2'd1:    rd_reg = reg1_q;
      2'd2:    rd_reg = reg2_q;
      2'd3:    rd_reg = reg3_q;
      default: rd_reg = {DATA_WIDTH{1'b0}};
    endcase
  end

  // Read side next state
  always @(*) begin
    rvalid_d = rvalid_q;
    rresp_d  = rresp_q;
    rdata_d  = rdata_q;
    if (ar_hs) begin
      rvalid_d = 1'b1;
      rresp_d  = rd_mapped ? RESP_OKAY : RESP_SLVERR;
      rdata_d  = rd_mapped ? rd_reg : {DATA_WIDTH{1'b0}};
    end else if (r_hs) begin
      rvalid_d = 1'b0;
    end
  end

  // ------------------------------------------------------------------
  // State registers: synchronous active-low reset, then q <= d
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held_q <= 1'b0;
      w_held_q  <= 1'b0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
      rvalid_q  <= 1'b0;
      rresp_q   <= RESP_OKAY;
      rdata_q   <= {DATA_WIDTH{1'b0}};
      reg0_q    <= {DATA_WIDTH{1'b0}};
      reg1_q    <= {DATA_WIDTH{1'b0}};
      reg2_q    <= {DATA_WIDTH{1'b0}};
      reg3_q    <= {DATA_WIDTH{1'b0}};
    end else begin
      aw_held_q <= aw_held_d;
      w_held_q  <= w_held_d;
      bvalid_q  <= bvalid_d;
      bresp_q   <= bresp_d;
      rvalid_q  <= rvalid_d;
      rresp_q   <= rresp_d;
      rdata_q   <= rdata_d;
      reg0_q    <= reg0_d;
      reg1_q    <= reg1_d;
      reg2_q    <= reg2_d;
      reg3_q    <= reg3_d;
    end
  end

  // Holding registers: capture a half of the write that arrives alone
  always @(posedge aclk) begin
    if (aw_hs && !do_write) begin
      aw_addr_q <= s_axil_awaddr;
    end
    if (w_hs && !do_write) begin
      w_data_q <= s_axil_wdata;
      w_strb_q <= s_axil_wstrb;
    end
  end

`ifdef FORMAL
  // ------------------------------------------------------------------
  // Handshake properties (interface_spec.md [req:AXIL-FORMAL])
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;

  // Start in reset
  always @(*) if (!f_past_valid) assume(!aresetn);

  // Manager: VALIDs low while in reset
  always @(*) begin
    if (!aresetn) begin
      assume(!s_axil_awvalid);
      assume(!s_axil_wvalid);
      assume(!s_axil_arvalid);
    end
  end

  // Manager: VALID and payload hold until READY
  always @(posedge aclk) begin
    if (f_past_valid && $past(aresetn) && aresetn) begin
      if ($past(s_axil_awvalid && !s_axil_awready)) begin
        assume(s_axil_awvalid);
        assume(s_axil_awaddr == $past(s_axil_awaddr));
      end
      if ($past(s_axil_wvalid && !s_axil_wready)) begin
        assume(s_axil_wvalid);
        assume(s_axil_wdata == $past(s_axil_wdata));
        assume(s_axil_wstrb == $past(s_axil_wstrb));
      end
      if ($past(s_axil_arvalid && !s_axil_arready)) begin
        assume(s_axil_arvalid);
        assume(s_axil_araddr == $past(s_axil_araddr));
      end
    end
  end

  // Outstanding request counters
  reg [1:0] f_aw_out;
  reg [1:0] f_w_out;
  reg [1:0] f_ar_out;
  always @(posedge aclk) begin
    if (!aresetn) begin
      f_aw_out <= 2'd0;
      f_w_out  <= 2'd0;
      f_ar_out <= 2'd0;
    end else begin
      f_aw_out <= f_aw_out + {1'b0, aw_hs} - {1'b0, b_hs};
      f_w_out  <= f_w_out  + {1'b0, w_hs}  - {1'b0, b_hs};
      f_ar_out <= f_ar_out + {1'b0, ar_hs} - {1'b0, r_hs};
    end
  end

  // State invariants: at most one request per direction, and a response is
  // valid exactly when an accepted request awaits it
  always @(*) begin
    if (f_past_valid) begin
      assert(!(aw_held_q && w_held_q));
      assert(!bvalid_q || (!aw_held_q && !w_held_q));
      assert(f_aw_out == {1'b0, (aw_held_q || bvalid_q)});
      assert(f_w_out  == {1'b0, (w_held_q || bvalid_q)});
      assert(f_ar_out == {1'b0, rvalid_q});
      assert((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
      assert((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
      assert((rresp_q != RESP_SLVERR) || (rdata_q == {DATA_WIDTH{1'b0}}));
    end
  end

  always @(posedge aclk) begin
    if (f_past_valid) begin
      if (!$past(aresetn)) begin
        // Responses low and channels ready after reset
        assert(!s_axil_bvalid);
        assert(!s_axil_rvalid);
        assert(s_axil_awready && s_axil_wready && s_axil_arready);
      end else begin
        // B holds, with a stable payload, until taken
        if ($past(s_axil_bvalid && !s_axil_bready)) begin
          assert(s_axil_bvalid);
          assert(s_axil_bresp == $past(s_axil_bresp));
        end
        // R holds, with a stable payload, until taken
        if ($past(s_axil_rvalid && !s_axil_rready)) begin
          assert(s_axil_rvalid);
          assert(s_axil_rresp == $past(s_axil_rresp));
          assert(s_axil_rdata == $past(s_axil_rdata));
        end
        // Response one cycle after the request, code by address policy
        if ($past(do_write)) begin
          assert(s_axil_bvalid);
          assert(s_axil_bresp == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR));
        end
        if ($past(ar_hs)) begin
          assert(s_axil_rvalid);
          assert(s_axil_rresp == ($past(rd_mapped) ? RESP_OKAY : RESP_SLVERR));
          assert(s_axil_rdata == ($past(rd_mapped) ? $past(rd_reg) : {DATA_WIDTH{1'b0}}));
        end
        // No response without a request
        if (!$past(s_axil_bvalid) && s_axil_bvalid) assert($past(do_write));
        if (!$past(s_axil_rvalid) && s_axil_rvalid) assert($past(ar_hs));
      end
    end
  end

  // Covers: the promised behaviour is reachable
  always @(posedge aclk) begin
    if (f_past_valid && $past(aresetn) && aresetn) begin
      cover(b_hs && (s_axil_bresp == RESP_OKAY));
      cover(b_hs && (s_axil_bresp == RESP_SLVERR));
      cover(r_hs && (s_axil_rresp == RESP_OKAY) && (s_axil_rdata != {DATA_WIDTH{1'b0}}));
      cover(r_hs && (s_axil_rresp == RESP_SLVERR));
      cover(aw_held_q && w_hs);
      cover(w_held_q && aw_hs);
      cover(aw_hs && w_hs);
      cover($past(s_axil_bvalid && !s_axil_bready) && b_hs);
      cover($past(s_axil_rvalid && !s_axil_rready) && r_hs);
      cover(s_axil_bvalid && s_axil_rvalid);
      cover(ar_hs && rd_mapped && (s_axil_araddr[3:2] == 2'd0) && (rd_reg != {DATA_WIDTH{1'b0}}));
      cover(ar_hs && rd_mapped && (s_axil_araddr[3:2] == 2'd1) && (rd_reg != {DATA_WIDTH{1'b0}}));
      cover(ar_hs && rd_mapped && (s_axil_araddr[3:2] == 2'd2) && (rd_reg != {DATA_WIDTH{1'b0}}));
      cover(ar_hs && rd_mapped && (s_axil_araddr[3:2] == 2'd3) && (rd_reg != {DATA_WIDTH{1'b0}}));
    end
  end
`endif

endmodule
=== END FILE ===
