// axi4_lite_regs_tb: self-checking directed testbench for axi4_lite_regs.
//
// Inputs change just after the falling edge of aclk; handshakes are sampled
// one time unit later, before the rising edge, so there is no race with the
// design. Expected values come from the testbench's own register model.
// Every failed check is reported with $error; passing checks are counted.
// The verdict line is printed once, just before $finish.

`define CHECK(cond, msg) begin if (cond) passed = passed + 1; else begin failed = failed + 1; $error(msg); end end
`define FAIL(msg) begin failed = failed + 1; $error(msg); end

module axi4_lite_regs_tb;

  localparam [1:0]   OKAY      = 2'b00;
  localparam [1:0]   SLVERR    = 2'b10;
  localparam integer TXN_LIMIT = 40;

  reg         aclk;
  reg         aresetn;
  reg  [3:0]  s_axil_awaddr;
  reg         s_axil_awvalid;
  wire        s_axil_awready;
  reg  [31:0] s_axil_wdata;
  reg  [3:0]  s_axil_wstrb;
  reg         s_axil_wvalid;
  wire        s_axil_wready;
  wire [1:0]  s_axil_bresp;
  wire        s_axil_bvalid;
  reg         s_axil_bready;
  reg  [3:0]  s_axil_araddr;
  reg         s_axil_arvalid;
  wire        s_axil_arready;
  wire [31:0] s_axil_rdata;
  wire [1:0]  s_axil_rresp;
  wire        s_axil_rvalid;
  reg         s_axil_rready;

  integer        passed;
  integer        failed;
  reg            finished;
  reg [8*64-1:0] nonce;
  integer        plusarg_ok;
  integer        k;
  reg [31:0]     model [0:3];

  axi4_lite_regs #(
      .ADDR_WIDTH(4),
      .DATA_WIDTH(32)
  ) dut (
      .aclk           (aclk),
      .aresetn        (aresetn),
      .s_axil_awaddr  (s_axil_awaddr),
      .s_axil_awvalid (s_axil_awvalid),
      .s_axil_awready (s_axil_awready),
      .s_axil_wdata   (s_axil_wdata),
      .s_axil_wstrb   (s_axil_wstrb),
      .s_axil_wvalid  (s_axil_wvalid),
      .s_axil_wready  (s_axil_wready),
      .s_axil_bresp   (s_axil_bresp),
      .s_axil_bvalid  (s_axil_bvalid),
      .s_axil_bready  (s_axil_bready),
      .s_axil_araddr  (s_axil_araddr),
      .s_axil_arvalid (s_axil_arvalid),
      .s_axil_arready (s_axil_arready),
      .s_axil_rdata   (s_axil_rdata),
      .s_axil_rresp   (s_axil_rresp),
      .s_axil_rvalid  (s_axil_rvalid),
      .s_axil_rready  (s_axil_rready)
  );

  initial begin
    aclk = 1'b0;
    forever #5 aclk = ~aclk;
  end

  // Address policy from interface_spec.md section 5
  function tb_mapped;
    input [3:0] a;
    begin
      tb_mapped = (a[1:0] == 2'b00);
    end
  endfunction

  // Byte-enable merge, written independently of the RTL
  function [31:0] tb_merge;
    input [31:0] old_v;
    input [31:0] new_v;
    input [3:0]  strb;
    begin
      tb_merge[7:0]   = strb[0] ? new_v[7:0]   : old_v[7:0];
      tb_merge[15:8]  = strb[1] ? new_v[15:8]  : old_v[15:8];
      tb_merge[23:16] = strb[2] ? new_v[23:16] : old_v[23:16];
      tb_merge[31:24] = strb[3] ? new_v[31:24] : old_v[31:24];
    end
  endfunction

  task drive_idle;
    begin
      s_axil_awvalid = 1'b0;
      s_axil_wvalid  = 1'b0;
      s_axil_arvalid = 1'b0;
      s_axil_bready  = 1'b0;
      s_axil_rready  = 1'b0;
      s_axil_awaddr  = 4'h0;
      s_axil_wdata   = 32'h0;
      s_axil_wstrb   = 4'h0;
      s_axil_araddr  = 4'h0;
    end
  endtask

  // One write and/or one read, run concurrently. Delays are in cycles:
  // aw_dly/w_dly/ar_dly from the start of the call, b_dly/r_dly from the
  // cycle the response is first seen. Must be called just after a falling
  // edge; returns just after a falling edge (the cycle after the last
  // response handshake), so consecutive calls are back to back.
  task automatic txn;
    input         do_wr;
    input [3:0]   waddr;
    input [31:0]  wdat;
    input [3:0]   wstb;
    input integer aw_dly;
    input integer w_dly;
    input integer b_dly;
    input         do_rd;
    input [3:0]   raddr;
    input integer ar_dly;
    input integer r_dly;
    integer    c;
    integer    wr_cycle;
    integer    rd_cycle;
    integer    b_first;
    integer    r_first;
    reg        aw_done;
    reg        w_done;
    reg        wr_fired;
    reg        b_seen;
    reg        b_done;
    reg        ar_done;
    reg        r_seen;
    reg        r_done;
    reg        b_hold;
    reg        r_hold;
    reg [1:0]  b_resp_h;
    reg [1:0]  r_resp_h;
    reg [31:0] r_data_h;
    reg [1:0]  exp_bresp;
    reg [1:0]  exp_rresp;
    reg [31:0] exp_rdata;
    begin
      aw_done   = !do_wr;
      w_done    = !do_wr;
      wr_fired  = 1'b0;
      b_seen    = 1'b0;
      b_done    = !do_wr;
      ar_done   = !do_rd;
      r_seen    = 1'b0;
      r_done    = !do_rd;
      b_hold    = 1'b0;
      r_hold    = 1'b0;
      b_resp_h  = OKAY;
      r_resp_h  = OKAY;
      r_data_h  = 32'h0;
      wr_cycle  = 0;
      rd_cycle  = 0;
      b_first   = 0;
      r_first   = 0;
      exp_bresp = tb_mapped(waddr) ? OKAY : SLVERR;
      exp_rresp = OKAY;
      exp_rdata = 32'h0;
      c = 0;
      while (!(b_done && r_done) && (c < TXN_LIMIT)) begin
        // Observe the outputs registered at the previous rising edge.
        if (b_hold) begin
          `CHECK(s_axil_bvalid, "BVALID held until BREADY")
          `CHECK(s_axil_bresp == b_resp_h, "BRESP stable while B waits")
        end
        if (r_hold) begin
          `CHECK(s_axil_rvalid, "RVALID held until RREADY")
          `CHECK((s_axil_rresp == r_resp_h) && (s_axil_rdata == r_data_h), "RRESP and RDATA stable while R waits")
        end
        if (s_axil_bvalid) begin
          `CHECK(!s_axil_awready && !s_axil_wready, "AWREADY and WREADY low while B is pending")
          if (!do_wr || b_done || !wr_fired) begin
            `FAIL("BVALID without a completed write")
          end else if (!b_seen) begin
            b_seen  = 1'b1;
            b_first = c;
            `CHECK((c - wr_cycle >= 1) && (c - wr_cycle <= 2), "write latency within 2 cycles")
            `CHECK(s_axil_bresp == exp_bresp, "BRESP matches the address policy")
          end
        end else if (do_wr && wr_fired && !b_seen && (c - wr_cycle >= 2)) begin
          `FAIL("write latency bound exceeded")
        end
        if (s_axil_rvalid) begin
          `CHECK(!s_axil_arready, "ARREADY low while R is pending")
          if (!do_rd || r_done || !ar_done) begin
            `FAIL("RVALID without an accepted read")
          end else if (!r_seen) begin
            r_seen  = 1'b1;
            r_first = c;
            `CHECK((c - rd_cycle >= 1) && (c - rd_cycle <= 2), "read latency within 2 cycles")
            `CHECK(s_axil_rresp == exp_rresp, "RRESP matches the address policy")
            `CHECK(s_axil_rdata == exp_rdata, "RDATA matches the register model")
          end
        end else if (do_rd && ar_done && !r_seen && (c - rd_cycle >= 2)) begin
          `FAIL("read latency bound exceeded")
        end

        // Drive this cycle's inputs.
        s_axil_awvalid = do_wr && !aw_done && (c >= aw_dly);
        s_axil_awaddr  = s_axil_awvalid ? waddr : ~waddr;
        s_axil_wvalid  = do_wr && !w_done && (c >= w_dly);
        s_axil_wdata   = s_axil_wvalid ? wdat : ~wdat;
        s_axil_wstrb   = s_axil_wvalid ? wstb : ~wstb;
        s_axil_bready  = do_wr && !b_done && (b_seen ? (c - b_first >= b_dly) : (b_dly == 0));
        s_axil_arvalid = do_rd && !ar_done && (c >= ar_dly);
        s_axil_araddr  = s_axil_arvalid ? raddr : ~raddr;
        s_axil_rready  = do_rd && !r_done && (r_seen ? (c - r_first >= r_dly) : (r_dly == 0));

        // Sample the handshakes that the coming rising edge completes.
        #1;
        if (s_axil_arvalid && s_axil_arready) begin
          ar_done   = 1'b1;
          rd_cycle  = c;
          exp_rresp = tb_mapped(raddr) ? OKAY : SLVERR;
          exp_rdata = tb_mapped(raddr) ? model[raddr[3:2]] : 32'h0;
        end
        if (s_axil_awvalid && s_axil_awready) aw_done = 1'b1;
        if (s_axil_wvalid && s_axil_wready) w_done = 1'b1;
        if (do_wr && !wr_fired && aw_done && w_done) begin
          wr_fired = 1'b1;
          wr_cycle = c;
          if (tb_mapped(waddr)) begin
            model[waddr[3:2]] = tb_merge(model[waddr[3:2]], wdat, wstb);
          end
        end
        b_hold   = s_axil_bvalid && !s_axil_bready;
        b_resp_h = s_axil_bresp;
        if (s_axil_bvalid && s_axil_bready) b_done = 1'b1;
        r_hold   = s_axil_rvalid && !s_axil_rready;
        r_resp_h = s_axil_rresp;
        r_data_h = s_axil_rdata;
        if (s_axil_rvalid && s_axil_rready) r_done = 1'b1;

        @(negedge aclk);
        c = c + 1;
      end

      if (!(b_done && r_done)) begin
        `FAIL("transaction did not complete within the cycle limit")
      end
      `CHECK(!s_axil_bvalid && !s_axil_rvalid, "no response left after the transaction")
      if (do_wr) begin
        `CHECK(s_axil_awready && s_axil_wready, "write channel ready in the cycle after B")
      end
      if (do_rd) begin
        `CHECK(s_axil_arready, "read channel ready in the cycle after R")
      end
      drive_idle;
    end
  endtask

  task automatic axi_write;
    input [3:0]   a;
    input [31:0]  d;
    input [3:0]   s;
    input integer aw_dly;
    input integer w_dly;
    input integer b_dly;
    begin
      txn(1'b1, a, d, s, aw_dly, w_dly, b_dly, 1'b0, 4'h0, 0, 0);
    end
  endtask

  task automatic axi_read;
    input [3:0]   a;
    input integer ar_dly;
    input integer r_dly;
    begin
      txn(1'b0, 4'h0, 32'h0, 4'h0, 0, 0, 0, 1'b1, a, ar_dly, r_dly);
    end
  endtask

  task automatic read_all;
    begin
      axi_read(4'h0, 0, 0);
      axi_read(4'h4, 0, 0);
      axi_read(4'h8, 0, 0);
      axi_read(4'hC, 0, 0);
    end
  endtask

  initial begin
    passed     = 0;
    failed     = 0;
    finished   = 1'b0;
    nonce      = {64{8'h00}};
    plusarg_ok = $value$plusargs("nirmaan_nonce=%s", nonce);
    model[0]   = 32'h0;
    model[1]   = 32'h0;
    model[2]   = 32'h0;
    model[3]   = 32'h0;
    aresetn    = 1'b0;
    drive_idle;

    // ---- Reset
    repeat (3) @(negedge aclk);
    `CHECK(!s_axil_bvalid && !s_axil_rvalid, "BVALID and RVALID low during reset")
    aresetn = 1'b1;
    `CHECK(s_axil_awready && s_axil_wready && s_axil_arready, "READY high after reset")

    // ---- Reset values
    read_all;

    // ---- Write then read every register
    axi_write(4'h0, 32'hDEADBEEF, 4'hF, 0, 0, 0);
    axi_read(4'h0, 0, 0);
    axi_write(4'h4, 32'h01234567, 4'hF, 0, 0, 0);
    axi_read(4'h4, 0, 0);
    axi_write(4'h8, 32'h89ABCDEF, 4'hF, 0, 0, 0);
    axi_read(4'h8, 0, 0);
    axi_write(4'hC, 32'hCAFEF00D, 4'hF, 0, 0, 0);
    axi_read(4'hC, 0, 0);
    read_all;

    // ---- AW and W ordering
    axi_write(4'h4, 32'h13579BDF, 4'hF, 0, 3, 0);  // AW first
    axi_read(4'h4, 0, 0);
    axi_write(4'h8, 32'h2468ACE0, 4'hF, 3, 0, 0);  // W first
    axi_read(4'h8, 0, 0);
    axi_write(4'h0, 32'hA5A55A5A, 4'hF, 0, 1, 0);  // AW then W next cycle
    axi_write(4'hC, 32'h5A5AA5A5, 4'hF, 1, 0, 0);  // W then AW next cycle
    axi_write(4'h0, 32'h0F0F0F0F, 4'hF, 2, 2, 0);  // both together after a gap
    read_all;

    // ---- Byte strobes: every pattern through the live and held W paths
    for (k = 0; k < 16; k = k + 1) begin
      axi_write(4'h4, 32'h0F1E2D3C + k * 32'h01010101, k[3:0], k % 2, 1 - (k % 2), 0);
      axi_read(4'h4, 0, 0);
    end
    axi_write(4'hC, 32'h11223344, 4'b0001, 0, 0, 0);
    axi_read(4'hC, 0, 0);
    axi_write(4'hC, 32'h55667788, 4'b1010, 0, 0, 0);
    axi_read(4'hC, 0, 0);
    axi_write(4'hC, 32'hFFFFFFFF, 4'b0000, 0, 0, 0);  // empty strobe: no change and OKAY
    axi_read(4'hC, 0, 0);

    // ---- Back-pressure on B and R
    axi_write(4'h0, 32'hC001D00D, 4'hF, 0, 0, 4);
    axi_read(4'h0, 0, 5);
    axi_write(4'h8, 32'h600DF00D, 4'hF, 2, 0, 3);
    axi_read(4'h8, 1, 2);

    // ---- Back-to-back transactions
    for (k = 0; k < 4; k = k + 1) begin
      axi_write({k[1:0], 2'b00}, 32'h10203040 ^ k, 4'hF, 0, 0, 0);
    end
    for (k = 0; k < 4; k = k + 1) begin
      axi_read({k[1:0], 2'b00}, 0, 0);
    end

    // ---- SLVERR policy for unmapped addresses
    axi_write(4'h1, 32'hFFFFFFFF, 4'hF, 0, 0, 0);
    axi_write(4'h2, 32'hFFFFFFFF, 4'hF, 0, 1, 0);
    axi_write(4'h3, 32'hFFFFFFFF, 4'hF, 1, 0, 0);
    axi_write(4'h5, 32'hFFFFFFFF, 4'hF, 0, 0, 0);
    axi_write(4'hE, 32'hFFFFFFFF, 4'hF, 0, 0, 0);
    axi_write(4'h6, 32'hFFFFFFFF, 4'hF, 0, 2, 3);
    axi_read(4'h1, 0, 0);
    axi_read(4'h3, 0, 0);
    axi_read(4'h5, 0, 0);
    axi_read(4'hE, 0, 0);
    axi_read(4'hB, 0, 3);
    read_all;

    // ---- Reads and writes in flight together
    txn(1'b1, 4'h0, 32'h0BADCAFE, 4'hF, 0, 0, 0, 1'b1, 4'h4, 0, 0);
    txn(1'b1, 4'h8, 32'h76543210, 4'h3, 2, 0, 1, 1'b1, 4'hC, 1, 3);
    txn(1'b1, 4'h0, 32'hFEEDFACE, 4'hF, 0, 0, 2, 1'b1, 4'h0, 3, 0);
    txn(1'b1, 4'h5, 32'hFFFFFFFF, 4'hF, 0, 0, 0, 1'b1, 4'hD, 0, 0);
    txn(1'b1, 4'hC, 32'h3C3C3C3C, 4'hF, 0, 3, 2, 1'b1, 4'h8, 0, 4);
    read_all;

    // ---- Reset during traffic: AW without W and a pending R
    s_axil_awaddr  = 4'h4;
    s_axil_awvalid = 1'b1;
    s_axil_araddr  = 4'h0;
    s_axil_arvalid = 1'b1;
    #1;
    `CHECK(s_axil_awready && s_axil_arready, "AW and AR accepted before reset")
    @(negedge aclk);
    s_axil_awvalid = 1'b0;
    s_axil_arvalid = 1'b0;
    `CHECK(!s_axil_awready && s_axil_wready && !s_axil_bvalid, "AW held while W is awaited")
    `CHECK(s_axil_rvalid, "R pending before reset")
    aresetn = 1'b0;
    @(negedge aclk);
    @(negedge aclk);
    `CHECK(!s_axil_bvalid && !s_axil_rvalid, "B and R cleared by reset")
    aresetn  = 1'b1;
    model[0] = 32'h0;
    model[1] = 32'h0;
    model[2] = 32'h0;
    model[3] = 32'h0;
    `CHECK(s_axil_awready && s_axil_wready && s_axil_arready, "READY high after reset during traffic")

    // W alone must not pair with the AW that reset discarded
    s_axil_wdata  = 32'hA5A50F0F;
    s_axil_wstrb  = 4'hF;
    s_axil_wvalid = 1'b1;
    #1;
    `CHECK(s_axil_wready, "W accepted after reset")
    @(negedge aclk);
    s_axil_wvalid = 1'b0;
    for (k = 0; k < 3; k = k + 1) begin
      `CHECK(!s_axil_bvalid, "no B for a write whose AW was discarded by reset")
      `CHECK(!s_axil_wready && s_axil_awready, "W held while AW is awaited")
      @(negedge aclk);
    end
    // A fresh AW completes the held W
    s_axil_awaddr  = 4'h8;
    s_axil_awvalid = 1'b1;
    #1;
    `CHECK(s_axil_awready, "AW accepted to complete the held W")
    @(negedge aclk);
    s_axil_awvalid = 1'b0;
    `CHECK(s_axil_bvalid && (s_axil_bresp == OKAY), "B with OKAY one cycle after the write completes")
    model[2] = 32'hA5A50F0F;
    s_axil_bready = 1'b1;
    #1;
    @(negedge aclk);
    s_axil_bready = 1'b0;
    `CHECK(!s_axil_bvalid && s_axil_awready && s_axil_wready, "B taken and write channel ready")
    drive_idle;
    read_all;

    // ---- Done
    @(negedge aclk);
    `CHECK(!s_axil_bvalid && !s_axil_rvalid, "bus idle at the end")
    finished = 1'b1;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

  // Watchdog: a hung handshake ends the run as a failure.
  initial begin : watchdog
    #200000;
    if (!finished) begin
      $error("watchdog: the test did not finish");
      $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
      $finish;
    end
  end

endmodule
